import {createHash} from 'node:crypto';
// Private fixture on stdin. Use the built Web application and the real loopback
// user router. No responses are intercepted or generated by the browser test.
import { chromium } from '@playwright/test';
import { preview } from 'vite';
import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const root=fileURLToPath(new URL('../',import.meta.url));
const tls=resolve(root,'../../.local/tls');
let input='';
for await (const chunk of process.stdin) input+=chunk;
const f=JSON.parse(input);
const upstream=new URL(f.api);
if(upstream.protocol!=='http:'||upstream.hostname!=='127.0.0.1'||!upstream.port ||
    f.origin!=='https://127.0.0.1:43122' || typeof f.token!=='string')throw Error('Expected a private loopback user fixture');
const server=await preview({root,configFile:false,logLevel:'silent',preview:{host:'127.0.0.1',port:43122,strictPort:true,
  https:{key:readFileSync(resolve(tls,'key.pem')),cert:readFileSync(resolve(tls,'cert.pem'))},
  proxy:{'/api/v1/':{target:upstream.origin,changeOrigin:false}}}});
let browser;
try {
  browser=await chromium.launch({channel:'chrome',headless:true});
  const context=await browser.newContext({baseURL:f.origin,ignoreHTTPSErrors:true,viewport:{width:1280,height:960}});
  await context.addCookies([{name:'__Host-orange-user',value:f.token,url:f.origin,secure:true,httpOnly:true,sameSite:'Lax'}]);
  const page=await context.newPage();
  page.setDefaultTimeout(15000);
  await page.goto('/agent/runs/'+encodeURIComponent(f.run)+'/s3');
  await page.getByRole('combobox',{name:'S3 来源'}).click();
  await page.locator('.ant-select-item-option-content').filter({hasText:'registered-data/team/approved/'}).click();
  await page.getByRole('button',{name:'授权读取此前缀 15 分钟'}).click();
  await page.getByRole('button',{name:'列出对象'}).click();
  await page.getByRole('button',{name:'medium.bin',exact:true}).click();
  await page.getByRole('button',{name:'读取此版本并生成附件'}).click();
  const download=page.waitForEvent('download');
  await page.getByRole('button',{name:'下载已校验附件'}).click();
  const file=await download;
  if(file.suggestedFilename()!=='medium.bin')throw Error('Wrong attachment filename');
  const bytes=readFileSync(await file.path());
  const sum=createHash('sha256').update(bytes).digest('hex');
  if(bytes.length!==3145728||sum!==createHash('sha256').update(Buffer.alloc(3145728)).digest('hex'))throw Error('Invalid downloaded object');
  if(f.screenshot)await page.screenshot({path:f.screenshot,fullPage:true});
  await page.getByRole('button',{name:'撤销 S3 授权'}).click();
  await page.getByText('已撤销',{exact:true}).waitFor();
  await page.reload();
  await page.getByText('已撤销',{exact:true}).waitFor();
  if(await page.getByRole('button',{name:'下载已校验附件'}).count())throw Error('Revoked download action exposed');
  process.stdout.write(JSON.stringify({listed:true,inspected:true,downloaded_bytes:bytes.length,sha256:sum,revoked_after_reload:true})+'\n');
} finally {
  if(browser)await browser.close();
  await server.close();
}
